referenceSolutions.javascript:
function resetTalliesBossReceipt(readings, k) {
  const a=readings; let out=[];
  let total=0;for(const x of a){total=x===0?0:total+x;out.push(total);}
  return out.reduce((s,x,i)=>s+(i+1)*x,0);
}

